# ══════════════════════════════════════════════════════════════════════════
# SYS-1.0 calibration coupon wizard — the human checkpoint for issue #13.
#
# Walks one coupon print run through the coupon build check, the Bambu
# Studio/X2D set-up, the print, the nine tests of docs/calibration.md §3,
# and a dated record with the go/no-go. It is resumable: every value lands
# in the state file below, so Ctrl-C is safe at any point — the divider
# joint (1 h) and the stack load (24 h) require stopping and resuming.
#
#   run:      bash scripts/calibration-wizard.sh
#   state:    build/calibration/state.env          (build/ is git-ignored)
#   records:  chosen at run time; default is <calibration doc dir>/calibration-records
#
# Sources of truth: docs/spec/docs/calibration.md §3–§5 (tests, criteria,
# permitted fixes, record table), docs/spec/docs/standard.md §5–§6, and
# docs/spec/docs/HANDOFF.md §Human checkpoints (the spec is vendored at
# docs/spec/). An agent must not close #13 or #14 — the record stage prints
# the gh commands for the human to run.
# Re-run the calibration (calibration §6) after a new filament brand or
# type, a new nozzle, a major Bambu Studio upgrade, any master geometry
# change, or a new spool whose first box shows a fit problem.
#
# Verify after editing:
#   bash -n scripts/calibration-wizard.sh
#   docker run --rm -v "$PWD/scripts":/mnt:ro koalaman/shellcheck:stable \
#     -e SC1087,SC2329 /mnt/calibration-wizard.sh
#   and a scripted-stdin dry run (prompts read plain lines when stdin is not
#   a TTY); afterwards delete build/calibration/ so the real run starts fresh.
# The two shellcheck exclusions are quirks of the skill's wizard library
# above the STAGES marker, which stays byte-identical and is never edited.
# ══════════════════════════════════════════════════════════════════════════

run_wizard() {

TOTAL_STAGES=18

# ── Paths and state ───────────────────────────────────────────────────────

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(dirname -- "$SCRIPT_DIR")
STATE_DIR="$REPO_ROOT/build/calibration"
ENV_FILE="$STATE_DIR/state.env"
mkdir -p "$STATE_DIR"

# The vendored spec first, then a pre-move sibling checkout if one exists.
calibration_doc=""
for candidate in \
  "$REPO_ROOT/docs/spec/docs/calibration.md" \
  "$REPO_ROOT/../research/3d-printed-stackable-portable-storage/docs/calibration.md" \
  "$REPO_ROOT/../../research/3d-printed-stackable-portable-storage/docs/calibration.md" \
  "$REPO_ROOT/../3d-printed-stackable-portable-storage/docs/calibration.md"; do
  if [[ -f "$candidate" ]]; then
    calibration_doc="$candidate"
    break
  fi
done
if [[ -n "$calibration_doc" ]]; then
  default_record_dir="$(dirname -- "$calibration_doc")/calibration-records"
else
  default_record_dir="$STATE_DIR/records"
fi

# The FreeCAD pin lives in one place — the justfile — never retype it here.
freecad_version=""
if [[ -f "$REPO_ROOT/justfile" ]]; then
  freecad_version=$(sed -n 's/^freecad_version[[:space:]]*:=[[:space:]]*"\([^"]*\)".*/\1/p' "$REPO_ROOT/justfile" | head -n 1 | tr -d '[:space:]')
fi
freecad_version=${freecad_version:-1.0.0}
freecad_image="boxgen/freecad:${freecad_version}"

# ── Helpers ───────────────────────────────────────────────────────────────

val() { _existing "$1" || true; }

dashv() {
  if [[ -n "${1:-}" ]]; then printf '%s' "$1"; else printf '—'; fi
}

note_or() {
  if [[ -n "${1:-}" ]]; then printf '%s' "$1"; else printf '%s' "${2:-—}"; fi
}

is_num() { [[ "${1:-}" =~ ^[0-9]+([.][0-9]+)?$ ]]; }

delta_mm() {
  awk -v a="$1" -v b="$2" 'BEGIN { d = a - b; if (d < 0) d = -d; printf "%.2f", d }'
}

esc() { printf '%s' "${1:-}" | tr '\n' ' ' | sed 's/|/\\|/g'; }

join_commas() {
  local out="" item
  for item in "$@"; do
    if [[ -z "$out" ]]; then out="$item"; else out="$out, $item"; fi
  done
  printf '%s' "$out"
}

rel() { printf '%s' "${1#"$REPO_ROOT"/}"; }

hash_of() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | cut -c1-12
  else
    printf 'n/a'
  fi
}

# outside_range VALUE LOW HIGH: true when VALUE is a number outside [LOW, HIGH].
outside_range() {
  local value="${1:-}"
  if ! is_num "$value"; then
    return 1
  fi
  awk -v v="$value" -v lo="$2" -v hi="$3" 'BEGIN { exit !(v < lo || v > hi) }'
}

# at_least VALUE BOUND: true when VALUE is a number >= BOUND.
at_least() {
  local value="${1:-}"
  if ! is_num "$value"; then
    return 1
  fi
  awk -v v="$value" -v b="$2" 'BEGIN { exit !(v >= b) }'
}

# fmt_minutes MINUTES: "65 min" below two hours, "24.2 h" above.
fmt_minutes() {
  local minutes="${1:-0}"
  if ! is_num "$minutes"; then
    minutes=0
  fi
  if (( minutes >= 120 )); then
    awk -v m="$minutes" 'BEGIN { printf "%.1f h", m / 60 }'
  else
    printf '%s min' "$minutes"
  fi
}

# check_tolerance KEY LOW HIGH LABEL: warns when a measured value recorded as
# passing sits outside the calibration §4 tolerance (a record slip, not a stop).
check_tolerance() {
  local value
  value=$(val "$1")
  if outside_range "$value" "$2" "$3"; then
    warn "$4 measured ${value} mm — outside its pass tolerance (calibration §4); recorded as pass"
  fi
}

# coupon_missing: sets COUPON_MISSING to the absent coupon artifacts.
coupon_missing() {
  local f
  COUPON_MISSING=()
  for f in report.json body.stl lid.stl box.step; do
    if [[ ! -s "$COUPON_DIR/$f" ]]; then COUPON_MISSING+=("$f"); fi
  done
}

# todo: false (and says so) for stages before the fast-forward point.
todo() {
  if (( _STAGE_INDEX >= STAGE_FROM )); then
    return 0
  fi
  note "(skipped: already done in an earlier session)"
  return 1
}

# ask_or KEY DEFAULT PROMPT: like ask, but a first run offers DEFAULT.
ask_or() {
  local key="$1" default="$2" current=""
  current=$(val "$key")
  if [[ -n "$current" ]]; then
    ask "$key" "$3"
  else
    ask "$key" "$3 [default: ${default}]"
    if [[ -z "${!key}" ]]; then printf -v "$key" '%s' "$default"; fi
  fi
  write_env "$key" "${!key}"
}

# ask_val KEY PROMPT: a remembered free-text value.
ask_val() {
  ask "$1" "$2"
  write_env "$1" "${!1}"
}

# ask_mm KEY PROMPT: a remembered millimetre value (a number or n/a).
ask_mm() {
  local key="$1" value=""
  while :; do
    ask "$key" "$2"
    value=${!key}
    if [[ -z "$value" || "$value" =~ ^[0-9]+([.][0-9]+)?$ || "$value" == "n/a" || "$value" == "N/A" ]]; then
      break
    fi
    warn "enter a number in mm, n/a, or Enter to keep the current value"
  done
  write_env "$key" "$value"
}

# verdict KEY "Test label": a pass/fail capture.
verdict() {
  local key="$1" label="$2" value=""
  while :; do
    ask "$key" "$label — pass or fail:"
    value=${!key}
    case "${value,,}" in
      pass|p|y|yes) value="pass"; break ;;
      fail|f|n|no) value="fail"; break ;;
    esac
    warn "enter pass or fail"
  done
  printf -v "$key" '%s' "$value"
  write_env "$key" "$value"
}

# on_fail KEY FIX: after a verdict, record the observation and name the fix.
on_fail() {
  local key="$1" fix="$2"
  if [[ "${!key}" == "fail" ]]; then
    warn "Recorded as failed. Permitted fix: ${fix}"
    ask_val "${key}_NOTE" "Short note for the record (what you saw):"
  fi
}

# gate "question" "advice": a confirmation that stops the wizard cleanly.
gate() {
  if confirm "$1"; then
    return 0
  fi
  warn "${2:-not done yet}"
  return 1
}

# wait_ok KEY MINUTES LABEL: warns when a load test has not run long enough,
# and records the elapsed time so the record states the real durations.
wait_ok() {
  local key="$1" need="$2" label="$3" started="" now=0 elapsed=0 derive=""
  started=$(val "$key")
  if [[ -z "$started" ]]; then
    warn "no ${label} start recorded — run its set-up stage first"
    return 0
  fi
  if ! is_num "$started"; then
    warn "${label} start timestamp looks corrupt — fix ${key} in ${ENV_FILE} and re-run the set-up stage"
    return 0
  fi
  now=$(date +%s)
  elapsed=$(( (now - started) / 60 ))
  derive="${key%_TS}"
  write_env "${derive}_ELAPSED_MIN" "$elapsed"
  if (( elapsed < need )); then
    warn "${label} has run $(fmt_minutes "$elapsed"); it needs at least $(fmt_minutes "$need") — Ctrl-C and resume later (values are remembered)"
  else
    say "${label}: $(fmt_minutes "$elapsed") elapsed — wait satisfied"
  fi
}

# Permitted fixes per test (calibration §3 last paragraph, §3.8–§3.9,
# standard §4.4, §6). Anything else is architecture and needs an ADR.
FIX1="base tight: elephant-foot compensation 0.15–0.20 mm, or increase the base clearance up to 0.30 mm per side (standard §6); base loose or rocking: record it — the base/lip profile is architecture"
FIX2="same fit family as test 1 (elephant-foot compensation or the permitted base clearance); the stack pitch and lip are architecture"
FIX3="loose: add a second pair of ribs or increase the skirt depth; tight: lid clearance may go to 0.35 mm per side (standard §4.4); never add a latch (calibration §3.3)"
FIX4="under/over-extrusion: dry the filament (65 °C for 8 h) and re-check flow; the tolerance is 2.0 ± 0.1 mm (1.2 ± 0.1 mm for the base side shell)"
FIX5="under-extrusion at the fillets: dry and flow-check the filament; the radii themselves are architecture"
FIX6="record what you saw; dry and flow-check the filament; the divider junction geometry is architecture"
FIX7="record what you saw; if the failure is floor creep or deflection, the permitted floor fix (2.4 mm slab) applies when deflection exceeds 1.0 mm (calibration §3.8); a cracked lip or wall has no permitted parameter change — stop and record it for a system decision"
FIX8="apply the 2.4 mm floor (a 0.4 mm slab above the 2.0 mm floor), record it, and reprint — then re-run the coupon (calibration §3.8)"
FIX9="dry the filament and reprint before continuing (calibration §3.9)"
FIXES=("" "$FIX1" "$FIX2" "$FIX3" "$FIX4" "$FIX5" "$FIX6" "$FIX7" "$FIX8" "$FIX9")

# ── Opening ───────────────────────────────────────────────────────────────

banner "SYS-1.0 calibration coupon"

say "1–6 prepare and print · 7–12 the fit and finish tests · 13–17 the load-test set-ups and inspections · 18 the record."
if [[ -n "$calibration_doc" ]]; then
  note "Procedure: $(rel "$calibration_doc") §3–§4 — this wizard follows it."
  if ! grep -q "two coupons and one lid" "$calibration_doc"; then
    warn "the calibration document does not read like the revision this wizard follows — re-check it (and this script) before trusting the walkthrough"
  fi
else
  warn "docs/calibration.md was not found beside this repository; the wizard carries the tests itself."
fi

ask STAGE_FROM "Start at stage (Enter = 1; N to fast-forward, e.g. 15 after the waits):"
STAGE_FROM=${STAGE_FROM:-1}
if [[ ! "$STAGE_FROM" =~ ^[0-9]+$ ]] || (( STAGE_FROM < 1 )); then
  STAGE_FROM=1
fi
if (( STAGE_FROM > TOTAL_STAGES )); then
  STAGE_FROM=$TOTAL_STAGES
fi

while :; do
  ask_or CAL_ITERATION "${CAL_ITERATION:-1}" "Coupon iteration (1 = the first print; 2+ = a reprint after a fix):"
  if [[ "$CAL_ITERATION" =~ ^[0-9]+$ ]] && (( CAL_ITERATION >= 1 )); then
    break
  fi
  warn "enter a whole number, 1 or higher"
  write_env CAL_ITERATION ""
done
P="CAL${CAL_ITERATION}_"
ask_or CAL_RECORD_DIR "$default_record_dir" "Directory for the record files:"

# ── Stage 1: coupon build ────────────────────────────────────────────────

stage "Coupon build"
if todo; then
  COUPON_DIR="$REPO_ROOT/build/coupon"
  coupon_missing
  if (( ${#COUPON_MISSING[@]} )); then
    warn "missing from build/coupon: ${COUPON_MISSING[*]}"
    say "Build the coupon with the pinned image (the host has no cargo or FreeCAD by design):"
    step "docker build --build-arg FREECAD_VERSION=${freecad_version} -f docker/freecad.Dockerfile -t ${freecad_image} ."
    step "docker run --rm -u \"\$(id -u):\$(id -g)\" -e HOME=/tmp/boxgen-home -e FREECAD_USER_HOME=/tmp/boxgen-freecad -e CARGO_HOME=/tmp/boxgen-cargo -e CARGO_TARGET_DIR=/app/build/docker-target -v \"\$PWD\":/app -w /app ${freecad_image} cargo run -- coupon"
    if command -v docker >/dev/null 2>&1 && confirm "Run those two commands now?"; then
      ( cd "$REPO_ROOT" && docker build --build-arg "FREECAD_VERSION=${freecad_version}" -f docker/freecad.Dockerfile -t "$freecad_image" . )
      ( cd "$REPO_ROOT" && docker run --rm -u "$(id -u):$(id -g)" -e HOME=/tmp/boxgen-home -e FREECAD_USER_HOME=/tmp/boxgen-freecad -e CARGO_HOME=/tmp/boxgen-cargo -e CARGO_TARGET_DIR=/app/build/docker-target -v "$PWD":/app -w /app "$freecad_image" cargo run -- coupon )
      coupon_missing
    fi
    if (( ${#COUPON_MISSING[@]} )); then
      warn "still missing: ${COUPON_MISSING[*]} — run the commands above, then re-run this wizard."
      return
    fi
  fi
  say "build/coupon is ready; body.stl and lid.stl are the print files."
  say "  body.stl $(stat -c%s "$COUPON_DIR/body.stl") bytes · lid.stl $(stat -c%s "$COUPON_DIR/lid.stl") bytes"
  write_env "${P}BODY_SHA" "$(hash_of "$COUPON_DIR/body.stl")"
  write_env "${P}LID_SHA" "$(hash_of "$COUPON_DIR/lid.stl")"
  if [[ -n "$calibration_doc" ]]; then
    write_env "${P}DOC_SHA" "$(hash_of "$calibration_doc")"
  fi
  if grep -Eq '"coupon"' "$COUPON_DIR/report.json"; then
    if ! grep -Eq '"floor_fillet_mm": *2\.0' "$COUPON_DIR/report.json"; then
      warn "report.json: body.floor_fillet_mm is not the standard 2.0 mm — check the build warnings"
    fi
    if ! grep -Eq '"roundover_mm": *1\.0' "$COUPON_DIR/report.json"; then
      warn "report.json: lid.roundover_mm is not 1.0 mm — the roundover was reduced; check the build warnings"
    fi
    if ! grep -Eq '"ribs": *true' "$COUPON_DIR/report.json"; then
      warn "report.json: lid.ribs is not true — the coupon lid must be ribbed"
    fi
  else
    warn "report.json has no coupon section — re-run 'boxgen coupon'"
  fi
  say "Print files: body.stl twice (two coupons) and lid.stl once."
fi

# ── Stage 2: the kit ─────────────────────────────────────────────────────

stage "Gather the kit"
if todo; then
  say "The coupon run needs (HANDOFF §Human checkpoints):"
  step "Bambu Lab X2D with the 0.4 mm hardened steel main nozzle installed"
  step "Bambu Lab PETG Basic spool (note the spool/lot for the record)"
  step "Calipers"
  step "5 kg weight with a 20 mm diameter foot (divider joint)"
  step "10 kg weight and a flat plate that spans the top coupon (stack load)"
  step "A Gridfinity baseplate — optional; test 1 can use the second coupon's lip"
  step "A clear 24 h window where the loaded stack sits undisturbed"
  step "Bambu Studio, with the production recipe ready"
  if ! gate "Everything on hand?" "gather what is missing before the print and load tests; you can continue and stop any time"; then
    return
  fi
fi

# ── Stage 3: Bambu Studio selectors ──────────────────────────────────────

stage "Bambu Studio: machine, plate, filament"
if todo; then
  say "In Bambu Studio, set the three selectors:"
  step "Printer: Bambu Lab X2D, 0.4 mm nozzle profile — the main nozzle must be the 0.4 mm hardened steel one"
  step "Plate: Textured PEI Plate"
  step "Filament: Bambu PETG Basic"
  note "Labels drift a little between Bambu Studio versions; the values are the recipe."
  note "Do not enable active chamber heating for PETG Basic (standard §5)."
  if ! gate "Selectors set?" "set them and re-run — values are remembered"; then
    return
  fi
fi

# ── Stage 4: the production recipe ───────────────────────────────────────

stage "Bambu Studio: production recipe"
if todo; then
  say "Apply the standard's print recipe (standard §5), as overrides on the 0.20 mm profile:"
  step "Wall loops: 5                 (Strength → Shell)"
  step "Top shell layers: 5           (Strength → Shell)"
  step "Bottom shell layers: 5        (Strength → Shell)"
  step "Sparse infill density: 40 %   (Strength → Infill)"
  step "Sparse infill pattern: Gyroid (Strength → Infill)"
  step "Support: disabled             (Support → Enable support)"
  step "Brim: 5 mm                   (Others → Bed adhesion)"
  step "Layer height: 0.20 mm — no variable or adaptive layers on the lip or lid interface (standard §5)"
  note "Leave elephant-foot compensation at its default for this first print; 0.15–0.20 mm is the one slicer value the standard lets you tune (§6)."
  if ! gate "Recipe applied?" "apply the recipe and re-run — values are remembered"; then
    return
  fi
fi

# ── Stage 5: plate layout and slice ──────────────────────────────────────

stage "Plate layout and slice"
if todo; then
  say "Add the coupon print files from build/coupon/:"
  step "body.stl — add it twice (Add again, or import once and clone it)"
  step "lid.stl — add it once"
  say "Orientation (standard §5):"
  step "Bodies: as exported — base on the plate, opening up"
  step "Lid: flip it — top surface on the plate, skirt up (rotate 180° about X)"
  step "All three parts sit on the plate (z = 0) and do not touch"
  say "Slice, then check the preview:"
  step "0.20 mm layers, brim about 5 mm, no supports, gyroid only in thick regions"
  step "Two coupon bodies plus the lid on one plate"
  if ! gate "Sliced and checked?" "fix the layout and re-run — values are remembered"; then
    return
  fi
fi

# ── Stage 6: print and capture the record header ─────────────────────────

stage "Print and release the parts"
if todo; then
  say "Send the plate to the X2D and print."
  step "If the spool saw >50 % RH for >72 h: dry it at 65 °C for 8 h first (standard §5)"
  step "Let the plate cool before removing the parts; remove the brim; deburr the bottom edges"
  step "Test the fits as printed — do not sand the base, lip, or skirt"
  ask_or "${P}DATE" "$(date +%F)" "Print date (YYYY-MM-DD):"
  ask_val "${P}SPOOL" "Filament spool / lot (as on the spool label):"
  ask_or "${P}NOZZLE" "0.4 mm hardened steel" "Nozzle:"
  ask_val "${P}STUDIO" "Bambu Studio version (optional; Enter to skip):"
  ask_val "${P}SLICE_H" "Slicer print-time estimate in hours (optional; Enter to skip):"
  ask_val "${P}SLICE_G" "Slicer filament estimate in grams (optional; Enter to skip):"
  say "Call the two coupons A and B: A is the one you carry through the fit tests, B is the stack bottom."
fi

# ── Stage 7: test 1 · base fit ───────────────────────────────────────────

stage "Test 1 · Base fit"
if todo; then
  say "Place coupon A on a Gridfinity baseplate, or on coupon B's lip, and press it down by hand (calibration §3.1)."
  step "Pass: seats with slight play; no force, no rocking (calibration §4)."
  verdict "${P}TEST1" "Base fit"
  on_fail "${P}TEST1" "$FIX1"
fi

# ── Stage 8: test 2 · stack fit ──────────────────────────────────────────

stage "Test 2 · Stack fit"
if todo; then
  say "Stack A on B, then lift A off (calibration §3.2)."
  step "Pass: self-centres, no wobble, separates with a deliberate pull (calibration §4)."
  verdict "${P}TEST2" "Stack fit"
  on_fail "${P}TEST2" "$FIX2"
fi

# ── Stage 9: test 3 · lid fit ────────────────────────────────────────────

stage "Test 3 · Lid fit"
if todo; then
  say "On coupon A: insert and remove the lid 20 times, lifting it by the finger hole. Then invert the coupon and shake gently (calibration §3.3)."
  step "Pass: the lid stays in place against the ribs; removable by hand (calibration §4)."
  verdict "${P}TEST3" "Lid fit"
  on_fail "${P}TEST3" "$FIX3"
fi

# ── Stage 10: test 4 · shell thickness ───────────────────────────────────

stage "Test 4 · Shell thickness"
if todo; then
  say "Measure with calipers (calibration §3.4). Every value is 2.0 ± 0.1 mm; the base side shell is 1.2 ± 0.1 mm."
  ask_mm "${P}WALL_MM" "Body wall (mm):"
  ask_mm "${P}LIP_MM" "Lip wall (mm):"
  ask_mm "${P}FLOOR_MM" "Floor (mm):"
  ask_mm "${P}PLATE_MM" "Lid plate (mm):"
  ask_mm "${P}BASE_MM" "Base side shell (mm; n/a if unreachable):"
  verdict "${P}TEST4" "Shell thickness"
  if [[ "$(val "${P}TEST4")" == "pass" ]]; then
    check_tolerance "${P}WALL_MM" 1.9 2.1 "body wall"
    check_tolerance "${P}LIP_MM" 1.9 2.1 "lip wall"
    check_tolerance "${P}FLOOR_MM" 1.9 2.1 "floor"
    check_tolerance "${P}PLATE_MM" 1.9 2.1 "lid plate"
    check_tolerance "${P}BASE_MM" 1.1 1.3 "base side shell"
  fi
  on_fail "${P}TEST4" "$FIX4"
fi

# ── Stage 11: test 5 · corner radii ──────────────────────────────────────

stage "Test 5 · Corner radii"
if todo; then
  say "Inspect the outer corners (3.75 mm), the body's inner corners (1.75 mm), and the joint fillets (2.0 mm) (calibration §3.5)."
  step "Pass: no sharp internal corner above the base; no visible under-extrusion at the fillets (calibration §4)."
  verdict "${P}TEST5" "Corner radii"
  on_fail "${P}TEST5" "$FIX5"
fi

# ── Stage 12: test 9 · fit-surface finish ────────────────────────────────

stage "Test 9 · Fit-surface finish"
if todo; then
  say "Check the lip and the lid interface for stringing, blobs, or zits that would affect the fit (calibration §3.9)."
  step "Pass: none. If present: dry the filament and reprint before continuing (calibration §3.9)."
  verdict "${P}TEST9" "Surface"
  on_fail "${P}TEST9" "$FIX9"
fi

# ── Stage 13: test 6 · divider joint, set-up ─────────────────────────────

stage "Test 6 · Divider joint — set up"
if todo; then
  say "Press the 5 kg weight, 20 mm foot, centred on coupon B's divider top (calibration §3.6)."
  divider_ts=$(val "${P}DIVIDER_TS")
  if [[ -n "$divider_ts" ]]; then
    say "The 1 h clock is already running, started $(date -d "@$divider_ts" '+%F %T')."
    if confirm "Start the clock fresh now?"; then
      write_env "${P}DIVIDER_TS" "$(date +%s)"
    fi
  else
    write_env "${P}DIVIDER_TS" "$(date +%s)"
    say "Clock started $(date '+%F %T')."
  fi
  say "Inspect at stage 14, at least one hour from the start — a natural stopping point."
fi

# ── Stage 14: test 6 · divider joint, inspect ────────────────────────────

stage "Test 6 · Divider joint — inspect"
if todo; then
  wait_ok "${P}DIVIDER_TS" 60 "Divider-joint load"
  say "Lift the 5 kg off coupon B and inspect the divider joints at the floor and the wall."
  step "Pass: no cracks, no whitening, no gaps after 5 kg for 1 h (calibration §4)."
  verdict "${P}TEST6" "Divider joint"
  on_fail "${P}TEST6" "$FIX6"
  say "Set up the stack load next (stage 15) — the 24 h window starts there."
fi

# ── Stage 15: test 7 · stack load, set-up ────────────────────────────────

stage "Test 7 · Stack load — set up"
if todo; then
  say "Stack the two coupons (A on B). Put the flat plate across the top coupon, then the 10 kg, so the load passes through the lip — not through the lid. Keep the lid off this rig (calibration §3.7)."
  ask_mm "${P}STACK_H0_MM" "Stack height before (mm; use the same datum you will measure after):"
  stack_ts=$(val "${P}STACK_TS")
  if [[ -n "$stack_ts" ]]; then
    say "The 24 h clock is already running, started $(date -d "@$stack_ts" '+%F %T')."
    if confirm "Start the clock fresh now?"; then
      write_env "${P}STACK_TS" "$(date +%s)"
    fi
  else
    write_env "${P}STACK_TS" "$(date +%s)"
    say "Clock started $(date '+%F %T')."
  fi
  note "The load stays on for 24 h at room temperature. Stage 16 (deflection) can be measured now or with the load still on later; stage 17 is the height-after check."
  say "Natural stopping point: resume at stage 16 at any time, and at stage 17 after ≥ 24 h."
fi

# ── Stage 16: test 8 · floor deflection ──────────────────────────────────

stage "Test 8 · Floor deflection"
if todo; then
  say "With the 10 kg on the stack — now, or at the final inspection — measure the bottom coupon's floor at its centre (calibration §3.8)."
  say "Criterion: deflection < 1.0 mm. Above 1.0 mm the only permitted fix is the 2.4 mm floor (0.4 mm slab) — record it and reprint."
  note "If the floor is unreachable with the rig in place, take the best equivalent 10 kg measurement you can and say how in the next prompt."
  ask_mm "${P}DEFLECT_MM" "Floor deflection (mm):"
  ask_val "${P}DEFLECT_HOW" "How you measured it (short note):"
  verdict "${P}TEST8" "Floor deflection"
  if [[ "$(val "${P}TEST8")" == "pass" ]] && at_least "$(val "${P}DEFLECT_MM")" 1.0; then
    warn "recorded as pass, but the deflection $(val "${P}DEFLECT_MM") mm is ≥ 1.0 mm (calibration §4)"
  fi
  on_fail "${P}TEST8" "$FIX8"
fi

# ── Stage 17: test 7 · stack load, after 24 h ────────────────────────────

stage "Test 7 · Stack load — after 24 h"
if todo; then
  wait_ok "${P}STACK_TS" 1440 "Stack load"
  say "With the load still on, measure the stack height again at the same datum, then take the load off."
  ask_mm "${P}STACK_H1_MM" "Stack height after (mm):"
  h0=$(val "${P}STACK_H0_MM")
  h1=$(val "${P}STACK_H1_MM")
  if is_num "$h0" && is_num "$h1"; then
    say "Height change: $(delta_mm "$h0" "$h1") mm (criterion: < 0.5 mm)"
  fi
  say "Inspect the bottom coupon's lip and floor for cracks or deflection."
  step "Pass: no cracks; height change < 0.5 mm after 10 kg for 24 h (calibration §4)."
  verdict "${P}TEST7" "Stack load"
  if [[ "$(val "${P}TEST7")" == "pass" ]] && is_num "$h0" && is_num "$h1" && at_least "$(delta_mm "$h0" "$h1")" 0.5; then
    warn "recorded as pass, but the height change $(delta_mm "$h0" "$h1") mm is ≥ 0.5 mm (calibration §4)"
  fi
  on_fail "${P}TEST7" "$FIX7"
fi

# ── Stage 18: the record ─────────────────────────────────────────────────

stage "Record and go/no-go"
if todo; then
  ask_val "${P}NOTES" "Anything else for the record? (Enter = none):"

  CAL_DIR="$CAL_RECORD_DIR"
  mkdir -p "$CAL_DIR"

  results=()
  fails=()
  n=1
  while (( n <= 9 )); do
    v=$(val "${P}TEST$n")
    case "$v" in
      pass) results+=("PASS") ;;
      fail) results+=("FAIL"); fails+=("$n") ;;
      *)    results+=("NOT RECORDED"); fails+=("$n") ;;
    esac
    n=$(( n + 1 ))
  done

  if (( ${#fails[@]} == 0 )); then gonogo="GO"; else gonogo="NO-GO"; fi

  date_v=$(dashv "$(val "${P}DATE")")
  spool_v=$(dashv "$(val "${P}SPOOL")")
  nozzle_v=$(dashv "$(val "${P}NOZZLE")")
  studio_v=$(dashv "$(val "${P}STUDIO")")
  slice_h=$(dashv "$(val "${P}SLICE_H")")
  slice_g=$(dashv "$(val "${P}SLICE_G")")
  body_sha=$(dashv "$(val "${P}BODY_SHA")")
  lid_sha=$(dashv "$(val "${P}LID_SHA")")
  doc_sha=$(val "${P}DOC_SHA")
  divider_min=$(val "${P}DIVIDER_ELAPSED_MIN")
  stack_min=$(val "${P}STACK_ELAPSED_MIN")
  notes_v=$(val "${P}NOTES")

  procedure_v="docs/calibration.md §3–§4 (not found beside the repository)"
  if [[ -n "$calibration_doc" ]]; then
    procedure_v="$(rel "$calibration_doc") §3–§4"
    if [[ -n "$doc_sha" ]]; then procedure_v+=" (sha256 ${doc_sha}…)"; fi
  fi

  m1=$(note_or "$(val "${P}TEST1_NOTE")" "seats with slight play, no rocking")
  m2=$(note_or "$(val "${P}TEST2_NOTE")" "self-centres, no wobble, separates by hand")
  m3=$(note_or "$(val "${P}TEST3_NOTE")" "20 cycles; stays in when inverted and shaken")
  m4="wall $(dashv "$(val "${P}WALL_MM")") mm · lip $(dashv "$(val "${P}LIP_MM")") mm · floor $(dashv "$(val "${P}FLOOR_MM")") mm · lid plate $(dashv "$(val "${P}PLATE_MM")") mm · base shell $(dashv "$(val "${P}BASE_MM")") mm"
  m5=$(note_or "$(val "${P}TEST5_NOTE")" "outer 3.75 · inner 1.75 · joints 2.0; no sharp internal corners")
  m6=$(note_or "$(val "${P}TEST6_NOTE")" "5 kg for $(fmt_minutes "${divider_min:-0}"): no cracks, whitening, or gaps")
  h0=$(val "${P}STACK_H0_MM")
  h1=$(val "${P}STACK_H1_MM")
  if is_num "$h0" && is_num "$h1"; then
    m7="height $h0 → $h1 mm (Δ $(delta_mm "$h0" "$h1") mm) — 10 kg for $(fmt_minutes "${stack_min:-0}")"
  else
    m7="10 kg for $(fmt_minutes "${stack_min:-0}"); height before/after: $h0 → $h1 mm"
  fi
  m8="$(dashv "$(val "${P}DEFLECT_MM")") mm under 10 kg — $(dashv "$(val "${P}DEFLECT_HOW")")"
  m9=$(note_or "$(val "${P}TEST9_NOTE")" "no stringing or blobs in the fit surfaces")

  table_rows="| 1 | Base fit | ${results[0]} | ${m1} |"$'\n'
  table_rows+="| 2 | Stack fit | ${results[1]} | ${m2} |"$'\n'
  table_rows+="| 3 | Lid fit | ${results[2]} | ${m3} |"$'\n'
  table_rows+="| 4 | Shell thickness | ${results[3]} | ${m4} |"$'\n'
  table_rows+="| 5 | Corner radii | ${results[4]} | ${m5} |"$'\n'
  table_rows+="| 6 | Divider joint | ${results[5]} | ${m6} |"$'\n'
  table_rows+="| 7 | Stack load | ${results[6]} | ${m7} |"$'\n'
  table_rows+="| 8 | Floor deflection | ${results[7]} | ${m8} |"$'\n'
  table_rows+="| 9 | Surface | ${results[8]} | ${m9} |"

  fail_block=""
  for n in "${fails[@]}"; do
    failure_note=$(val "${P}TEST${n}_NOTE")
    fail_block+="- **Test ${n}:** $(dashv "$failure_note") — permitted fix: ${FIXES[n]}"$'\n'
  done
  if [[ -z "$fail_block" ]]; then
    fail_block="_None — all nine criteria held on this print._"$'\n'
  fi

  if (( ${#fails[@]} == 0 )); then
    row_result="PASS"
    row_notes="iteration ${CAL_ITERATION}; all nine tests pass"
  else
    row_result="FAIL"
    row_notes="iteration ${CAL_ITERATION}; failed: $(join_commas "${fails[@]}") — see the record"
  fi
  row_notes=$(esc "$row_notes")
  row_date=$(esc "$date_v")
  row_spool=$(esc "$spool_v")
  row_nozzle=$(esc "$nozzle_v")

  slug=$(printf '%s' "$date_v" | tr -cd '0-9A-Za-z-')
  slug=${slug:-undated}
  RECORD_FILE="$CAL_DIR/calibration-coupon-${slug}-iter${CAL_ITERATION}.md"
  ISSUE_FILE="$CAL_DIR/issue-13-comment-${slug}-iter${CAL_ITERATION}.md"

  cat > "$RECORD_FILE" <<EOF
# Calibration coupon record — iteration ${CAL_ITERATION}

- **Date:** ${date_v}
- **Filament / spool:** ${spool_v}
- **Nozzle:** ${nozzle_v}
- **Bambu Studio:** ${studio_v}
- **Slicer estimate:** ${slice_h} h / ${slice_g} g
- **Coupon:** coupon-1x1-6U-v1 — 41.5 × 41.5 × 42.0 mm body, ribbed lid, built by \`boxgen coupon\`
- **Artifacts:** body.stl sha256 ${body_sha}…, lid.stl sha256 ${lid_sha}…
- **Procedure:** ${procedure_v}
- **Go/no-go:** **${gonogo}**

| # | Test | Result | Measurement / note |
| --- | --- | --- | --- |
${table_rows}

## Failures and permitted fixes

${fail_block}
## Calibration record row (docs/calibration.md §5)

| ${row_date} | ${row_spool} | ${row_nozzle} | ${row_result} | ${row_notes} |

## Notes

$(note_or "$notes_v" "_None._")
EOF

  cat > "$ISSUE_FILE" <<EOF
## Calibration coupon — iteration ${CAL_ITERATION}: ${gonogo}

- **Date:** ${date_v}
- **Filament / spool:** ${spool_v}
- **Nozzle:** ${nozzle_v}
- **Bambu Studio:** ${studio_v}
- **Artifacts:** body.stl sha256 ${body_sha}…, lid.stl sha256 ${lid_sha}…
- **Record file:** ${RECORD_FILE}

| # | Test | Result | Measurement / note |
| --- | --- | --- | --- |
${table_rows}

### Failures and permitted fixes

${fail_block}
$(if (( ${#fails[@]} == 0 )); then
  printf '**GO** — all nine acceptance criteria pass in iteration %s. The calibration record row (calibration.md §5) is in the record file; paste it into the record table and close #13. #14 (test box) is unblocked.' "$CAL_ITERATION"
else
  printf '**NO-GO** — failed or unrecorded: %s. Fix only the permitted parameters, reprint, and re-run the wizard as iteration %s.' "$(join_commas "${fails[@]}")" "$(( CAL_ITERATION + 1 ))"
fi)
EOF

  say "Record:     $(rel "$RECORD_FILE")"
  say "Issue text: $(rel "$ISSUE_FILE")"
  say "Record row: | ${row_date} | ${row_spool} | ${row_nozzle} | ${row_result} | ${row_notes} |"
  say "Paste that row into the calibration record table (docs/calibration.md §5)."
  if (( ${#fails[@]} == 0 )); then
    say "GO — all nine tests passed; only a pass unblocks #14."
    note "Re-run the calibration (calibration §6) after a new filament brand or type, a new nozzle, a major Bambu Studio upgrade, or any master geometry change."
    step "gh issue comment 13 --repo stijnklomp/boxgen --body-file '$(rel "$ISSUE_FILE")'"
    step "gh issue close 13 --repo stijnklomp/boxgen --comment 'Calibration passed (iteration ${CAL_ITERATION}); record: $(rel "$RECORD_FILE")' — run this yourself"
  else
    warn "NO-GO — failed or unrecorded: $(join_commas "${fails[@]}")"
    say "Permitted parameters only: lid clearance, friction ribs, elephant-foot compensation, drying, flow, or the 2.4 mm floor (calibration §3); anything else is architecture and needs an ADR."
    say "Reprint, then re-run this wizard — enter iteration $(( CAL_ITERATION + 1 )) for the fresh run."
    step "gh issue comment 13 --repo stijnklomp/boxgen --body-file '$(rel "$ISSUE_FILE")' — optional progress comment"
  fi
  note "An agent must not close #13 or #14 (HANDOFF §Human checkpoints); run the gh commands yourself."
fi

finish
}

run_wizard "$@"; exit
